CREATE TABLE IF NOT EXISTS social_destinations (id BIGSERIAL PRIMARY KEY,name VARCHAR(190) NOT NULL,provider VARCHAR(20) NOT NULL CHECK(provider IN ('telegram','vk','x','webhook')),endpoint TEXT,account_ref VARCHAR(255),encrypted_token TEXT NOT NULL,is_enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS publication_jobs (id BIGSERIAL PRIMARY KEY,page_id BIGINT NOT NULL REFERENCES cms_pages(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','processing','partial','published','failed','cancelled')),scheduled_at TIMESTAMP NOT NULL,destination_ids TEXT NOT NULL DEFAULT '[]',attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 5,next_attempt_at TIMESTAMP,last_error TEXT,locked_at TIMESTAMP,lock_token VARCHAR(64),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_publication_due ON publication_jobs(status,next_attempt_at,scheduled_at);
CREATE TABLE IF NOT EXISTS publication_deliveries (id BIGSERIAL PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES publication_jobs(id) ON DELETE CASCADE,destination_id BIGINT NOT NULL REFERENCES social_destinations(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,http_status INTEGER,response_excerpt TEXT,error_message TEXT,published_ref VARCHAR(500),last_attempt_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(job_id,destination_id));
INSERT INTO schema_migrations(version) VALUES('10.2.0') ON CONFLICT(version) DO NOTHING;
